/* unlink(2) - Demonstration of file deletion */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

#define TEMP_FILE "test_unlink_file.tmp"

int main(void) {
    int fd;

    // 1. Create the file (ensure it exists)
    fd = open(TEMP_FILE, O_CREAT | O_WRONLY, 0600);
    if (fd == -1) {
        perror("Error creating file");
        return EXIT_FAILURE;
    }
    close(fd);

    printf("Temporary file '%s' created.
", TEMP_FILE);

    // 2. Attempt to unlink (delete the name)
    if (unlink(TEMP_FILE) == 0) {
        printf("Successfully unlinked '%s'.\n", TEMP_FILE);
    } else {
        // Handle potential errors (e.g., permissions, read-only FS)
        fprintf(stderr, "Failed to unlink '%s': %s\n", TEMP_FILE, strerror(errno));
        // Try to clean up if partial failure occurred
        if (access(TEMP_FILE, F_OK) == 0) {
            remove(TEMP_FILE); 
        }
        return EXIT_FAILURE;
    }

    // 3. Verify deletion using access(2)
    if (access(TEMP_FILE, F_OK) == -1 && errno == ENOENT) {
        printf("Verification successful: File path no longer exists.\n");
    } else {
        fprintf(stderr, "Verification failed: File still accessible (errno %d).\n", errno);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
